// === Tab: mySketch ===
// https://openprocessing.org/sketch/2395029

let spheres;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	describe("circle packing of rotating points on spheres");
	frameRate(60);

	noFill();
	strokeWeight(2);
	stroke("purple");

	spheres = [];
	const S = max(width, height);
	for (let i = 0; i < (width+height); i++) {
		const a = random(TWO_PI);
		const s = random(5/S, S/8);
		const r = random(s/2, S/2-s/2);
		const x = cos(a) * r;
		const y = sin(a) * r;
		const newDotSphere = new DotSphere(createVector(x, y, 0), s);
		// space filling collision detection
		let notCollides = true;
		for (let s of spheres) {
			if (dist(s.pos.x, s.pos.y, newDotSphere.pos.x, newDotSphere.pos.y) < (s.sze + newDotSphere.sze)) {
				notCollides = false;
				break;
			}
		}
		if (notCollides) {
			spheres.push(newDotSphere);
		}
	}
	// console.log(spheres);
}

function draw() {
	background(0, 0, 8);
	orbitControl();
	lights();
	pointLight(255, 255, 255, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))-width/2, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-height/2, 250);
	specularMaterial(255);
	shininess(75);
	for (let s of spheres) {
		s.draw();
	}
}

function doubleClicked() {
	if (mouseButton === LEFT) setup();
}

// https://x.com/i/status/1845186249377587605
class DotSphere {
	constructor(pos, sze) {
		this.pos = pos;
		this.sze = sze;
		this.rotz = random(TWO_PI);
		this.rotzf = random(90, 270) * Math.sign(random()-0.5);
		this.arms = ~~random(1, 6);
		this.numh = random(3, this.sze/5);
		this.sa = random(TWO_PI); // start angle
		this.ra = random(30, 60) * Math.sign(random()-0.5); // rotating angle sphere
		this.da = random(-HALF_PI, HALF_PI); // delta angle for dots
		// this.clr = lerpColor(color("purple"), color("cyan"), noise(this.pos.x, this.pos.y, frameCount / (this.pos.x+this.pos.y)));
	}

	draw() {
		push();
		translate(this.pos.x, this.pos.y, this.pos.z);
		rotateZ(frameCount/this.rotzf+this.rotz)
		const dh = this.sze / this.numh;
		stroke(lerpColor(color("rgb(255,64,255)"), color("rgb(64,255,255)"), noise(this.pos.x, this.pos.y, frameCount / (this.pos.x+this.pos.y))));
		strokeWeight(dh/2);
		for (let arm = 0; arm < this.arms; arm++) {
			var a = this.sa + arm / this.arms * TWO_PI + frameCount/this.ra;
			for (let h = -this.sze; h <= this.sze + dh/2; h += dh) {
				var r = sqrt(this.sze * this.sze - h*h);
				var x = cos(a) * abs(r);
				const z = sin(a) * abs(r);
				const sw = map(z, -this.sze/2, this.sze/2, 0.5, dh*0.8)
				strokeWeight(sw);
				point (x, h, z)
				a += this.da;
			}
		}
		pop();
	}
}
